-- database/schema.sql
-- Generated by `python -m scripts.dump_schema` from the models. Do not edit by hand.
--
-- Customers, technicians and admins are three separate tables. Notifications,
-- messages and activity logs record the owner's role next to the id
-- (user_role / sender_role / recipient_role), because ids repeat across them.
--
-- Fresh install:   mysql -u root -p < database/schema.sql
-- (or let the app do it:  flask --app app upgrade-db)

CREATE DATABASE IF NOT EXISTS devtech CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE devtech;

-- activity_logs
CREATE TABLE IF NOT EXISTS activity_logs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_role VARCHAR(20), 
	user_id INTEGER, 
	action VARCHAR(100) NOT NULL, 
	details TEXT, 
	ip_address VARCHAR(45), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);

-- admins
CREATE TABLE IF NOT EXISTS admins (
	username VARCHAR(80) NOT NULL, 
	id INTEGER NOT NULL AUTO_INCREMENT, 
	email VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	full_name VARCHAR(100) NOT NULL, 
	phone VARCHAR(20), 
	is_active BOOL, 
	last_active DATETIME, 
	created_at DATETIME, 
	updated_at DATETIME, 
	display_name VARCHAR(60), 
	headline VARCHAR(120), 
	avatar_file VARCHAR(64), 
	avatar_icon VARCHAR(30), 
	avatar_color VARCHAR(20), 
	avatar_frame VARCHAR(20), 
	banner VARCHAR(20), 
	PRIMARY KEY (id), 
	UNIQUE (username), 
	UNIQUE (email)
);

-- contact_inquiries
CREATE TABLE IF NOT EXISTS contact_inquiries (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	subject VARCHAR(200) NOT NULL, 
	message TEXT NOT NULL, 
	status VARCHAR(20), 
	ip_address VARCHAR(45), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);

-- customers
CREATE TABLE IF NOT EXISTS customers (
	username VARCHAR(80) NOT NULL, 
	address VARCHAR(255), 
	city VARCHAR(50), 
	province VARCHAR(50), 
	postal_code VARCHAR(10), 
	latitude NUMERIC(10, 7), 
	longitude NUMERIC(10, 7), 
	birth_date DATE, 
	oauth_provider VARCHAR(20), 
	oauth_id VARCHAR(255), 
	id INTEGER NOT NULL AUTO_INCREMENT, 
	email VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	full_name VARCHAR(100) NOT NULL, 
	phone VARCHAR(20), 
	is_active BOOL, 
	last_active DATETIME, 
	created_at DATETIME, 
	updated_at DATETIME, 
	display_name VARCHAR(60), 
	headline VARCHAR(120), 
	avatar_file VARCHAR(64), 
	avatar_icon VARCHAR(30), 
	avatar_color VARCHAR(20), 
	avatar_frame VARCHAR(20), 
	banner VARCHAR(20), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_customers_oauth_identity UNIQUE (oauth_provider, oauth_id), 
	UNIQUE (username), 
	UNIQUE (email)
);

-- messages
CREATE TABLE IF NOT EXISTS messages (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	sender_role VARCHAR(20) NOT NULL, 
	sender_id INTEGER NOT NULL, 
	recipient_role VARCHAR(20) NOT NULL, 
	recipient_id INTEGER NOT NULL, 
	subject VARCHAR(200), 
	content TEXT NOT NULL, 
	is_read BOOL, 
	parent_id INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(parent_id) REFERENCES messages (id)
);

-- notifications
CREATE TABLE IF NOT EXISTS notifications (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_role VARCHAR(20) NOT NULL, 
	user_id INTEGER NOT NULL, 
	title VARCHAR(100) NOT NULL, 
	message TEXT NOT NULL, 
	type VARCHAR(20), 
	is_read BOOL, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);

-- products
CREATE TABLE IF NOT EXISTS products (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(100) NOT NULL, 
	description TEXT, 
	price NUMERIC(10, 2) NOT NULL, 
	category VARCHAR(50), 
	stock_quantity INTEGER, 
	compatibility VARCHAR(100), 
	image_url VARCHAR(255), 
	is_active BOOL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);

-- service_categories
CREATE TABLE IF NOT EXISTS service_categories (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(50) NOT NULL, 
	description TEXT, 
	icon VARCHAR(50), 
	is_active BOOL, 
	created_at DATETIME, 
	slug VARCHAR(50), 
	color VARCHAR(20) NOT NULL, 
	display_order INTEGER NOT NULL, 
	tagline VARCHAR(200), 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	UNIQUE (slug)
);

-- system_settings
CREATE TABLE IF NOT EXISTS system_settings (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	setting_key VARCHAR(50) NOT NULL, 
	value TEXT, 
	description VARCHAR(200), 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (setting_key)
);

-- technicians
CREATE TABLE IF NOT EXISTS technicians (
	username VARCHAR(80) NOT NULL, 
	address VARCHAR(255), 
	city VARCHAR(50), 
	province VARCHAR(50), 
	id_type VARCHAR(30), 
	id_number VARCHAR(50), 
	id_verified BOOL, 
	id_verified_at DATETIME, 
	id INTEGER NOT NULL AUTO_INCREMENT, 
	email VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	full_name VARCHAR(100) NOT NULL, 
	phone VARCHAR(20), 
	is_active BOOL, 
	last_active DATETIME, 
	created_at DATETIME, 
	updated_at DATETIME, 
	display_name VARCHAR(60), 
	headline VARCHAR(120), 
	avatar_file VARCHAR(64), 
	avatar_icon VARCHAR(30), 
	avatar_color VARCHAR(20), 
	avatar_frame VARCHAR(20), 
	banner VARCHAR(20), 
	PRIMARY KEY (id), 
	UNIQUE (username), 
	UNIQUE (email)
);

-- message_attachments
CREATE TABLE IF NOT EXISTS message_attachments (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	message_id INTEGER NOT NULL, 
	filename VARCHAR(64) NOT NULL, 
	original_name VARCHAR(255) NOT NULL, 
	mime_type VARCHAR(80) NOT NULL, 
	size_bytes INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(message_id) REFERENCES messages (id)
);

-- orders
CREATE TABLE IF NOT EXISTS orders (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	customer_id INTEGER NOT NULL, 
	order_number VARCHAR(50) NOT NULL, 
	total_amount NUMERIC(10, 2) NOT NULL, 
	status VARCHAR(20), 
	shipping_address VARCHAR(255), 
	recipient_name VARCHAR(100), 
	recipient_phone VARCHAR(20), 
	address_line VARCHAR(255), 
	city VARCHAR(50), 
	province VARCHAR(50), 
	postal_code VARCHAR(10), 
	latitude NUMERIC(10, 7), 
	longitude NUMERIC(10, 7), 
	payment_method VARCHAR(20), 
	payment_status VARCHAR(20), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (id), 
	UNIQUE (order_number)
);

-- services
CREATE TABLE IF NOT EXISTS services (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	category_id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description TEXT, 
	price NUMERIC(10, 2) NOT NULL, 
	estimated_hours INTEGER, 
	is_active BOOL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(category_id) REFERENCES service_categories (id)
);

-- shopping_carts
CREATE TABLE IF NOT EXISTS shopping_carts (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	customer_id INTEGER NOT NULL, 
	status VARCHAR(20), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (id)
);

-- support_tickets
CREATE TABLE IF NOT EXISTS support_tickets (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	customer_id INTEGER NOT NULL, 
	subject VARCHAR(200) NOT NULL, 
	message TEXT NOT NULL, 
	category VARCHAR(50), 
	status VARCHAR(20), 
	admin_response TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (id)
);

-- user_preferences
CREATE TABLE IF NOT EXISTS user_preferences (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	customer_id INTEGER NOT NULL, 
	language VARCHAR(10), 
	theme VARCHAR(20), 
	email_notifications BOOL, 
	sms_notifications BOOL, 
	booking_reminders BOOL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (customer_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (id)
);

-- bookings
CREATE TABLE IF NOT EXISTS bookings (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	booking_number VARCHAR(50) NOT NULL, 
	customer_id INTEGER NOT NULL, 
	service_id INTEGER NOT NULL, 
	device_type VARCHAR(50) NOT NULL, 
	description TEXT NOT NULL, 
	address VARCHAR(255), 
	booking_date DATE NOT NULL, 
	booking_time TIME NOT NULL, 
	status VARCHAR(20), 
	is_in_shop BOOL, 
	technician_id INTEGER, 
	assigned_at DATETIME, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (booking_number), 
	FOREIGN KEY(customer_id) REFERENCES customers (id), 
	FOREIGN KEY(service_id) REFERENCES services (id), 
	FOREIGN KEY(technician_id) REFERENCES technicians (id)
);

-- cart_items
CREATE TABLE IF NOT EXISTS cart_items (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	cart_id INTEGER NOT NULL, 
	product_id INTEGER NOT NULL, 
	quantity INTEGER, 
	price NUMERIC(10, 2), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(cart_id) REFERENCES shopping_carts (id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);

-- order_items
CREATE TABLE IF NOT EXISTS order_items (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	order_id INTEGER NOT NULL, 
	product_id INTEGER NOT NULL, 
	quantity INTEGER, 
	price NUMERIC(10, 2) NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);

-- service_ratings
CREATE TABLE IF NOT EXISTS service_ratings (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	booking_id INTEGER NOT NULL, 
	technician_id INTEGER NOT NULL, 
	customer_id INTEGER NOT NULL, 
	stars SMALLINT, 
	experience TEXT, 
	improvement TEXT, 
	submitted_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (booking_id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id), 
	FOREIGN KEY(technician_id) REFERENCES technicians (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (id)
);

-- tech_approval_requests
CREATE TABLE IF NOT EXISTS tech_approval_requests (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	booking_id INTEGER NOT NULL, 
	technician_id INTEGER NOT NULL, 
	requested_at VARCHAR(20), 
	findings TEXT, 
	proposed_work TEXT, 
	additional_cost FLOAT, 
	extra_days INTEGER, 
	status VARCHAR(20), 
	responded_at VARCHAR(20), 
	customer_response TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id), 
	FOREIGN KEY(technician_id) REFERENCES technicians (id)
);

-- tech_incident_reports
CREATE TABLE IF NOT EXISTS tech_incident_reports (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	booking_id INTEGER, 
	technician_id INTEGER NOT NULL, 
	reported_at VARCHAR(20), 
	type VARCHAR(32), 
	severity VARCHAR(16), 
	location VARCHAR(255), 
	description TEXT, 
	action_taken TEXT, 
	authorities_notified BOOL, 
	status VARCHAR(20), 
	reviewed_by VARCHAR(120), 
	reviewed_at VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id), 
	FOREIGN KEY(technician_id) REFERENCES technicians (id)
);

-- tech_intake_records
CREATE TABLE IF NOT EXISTS tech_intake_records (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	booking_id INTEGER NOT NULL, 
	recorded_at VARCHAR(20), 
	device_type VARCHAR(40), 
	device_model VARCHAR(120), 
	serial_number VARCHAR(80), 
	`condition` VARCHAR(20), 
	condition_notes TEXT, 
	accessories TEXT, 
	powers_on BOOL, 
	has_password BOOL, 
	password_note VARCHAR(255), 
	data_backup_consent BOOL, 
	customer_present BOOL, 
	photos_note TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (booking_id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id)
);

-- tech_job_logs
CREATE TABLE IF NOT EXISTS tech_job_logs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	booking_id INTEGER NOT NULL, 
	at VARCHAR(20), 
	by_name VARCHAR(120), 
	action VARCHAR(32), 
	text TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id)
);

-- tech_service_reports
CREATE TABLE IF NOT EXISTS tech_service_reports (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	booking_id INTEGER NOT NULL, 
	technician_id INTEGER NOT NULL, 
	status VARCHAR(20), 
	created_at VARCHAR(20), 
	updated_at VARCHAR(20), 
	submitted_at VARCHAR(20), 
	diagnosis TEXT, 
	tests TEXT, 
	work_performed TEXT, 
	hours_spent FLOAT, 
	outcome VARCHAR(32), 
	outcome_notes TEXT, 
	recommendations TEXT, 
	photos_note TEXT, 
	admin_note TEXT, 
	reviewed_by VARCHAR(120), 
	reviewed_at VARCHAR(20), 
	review_status VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id), 
	FOREIGN KEY(technician_id) REFERENCES technicians (id)
);

-- tech_uploaded_files
CREATE TABLE IF NOT EXISTS tech_uploaded_files (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	owner_type VARCHAR(20), 
	owner_id INTEGER, 
	booking_id INTEGER, 
	technician_id INTEGER NOT NULL, 
	filename VARCHAR(255), 
	original_name VARCHAR(255), 
	mime_type VARCHAR(80), 
	size_bytes INTEGER, 
	caption VARCHAR(255), 
	uploaded_at VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id), 
	FOREIGN KEY(technician_id) REFERENCES technicians (id)
);

-- transactions
CREATE TABLE IF NOT EXISTS transactions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	transaction_number VARCHAR(50) NOT NULL, 
	booking_id INTEGER, 
	order_id INTEGER, 
	customer_id INTEGER NOT NULL, 
	amount NUMERIC(10, 2) NOT NULL, 
	payment_method VARCHAR(50) NOT NULL, 
	payment_status VARCHAR(20), 
	reference_number VARCHAR(50), 
	gcash_reference VARCHAR(50), 
	receipt_image VARCHAR(255), 
	rejection_reason TEXT, 
	transaction_date DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (transaction_number), 
	FOREIGN KEY(booking_id) REFERENCES bookings (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id), 
	FOREIGN KEY(customer_id) REFERENCES customers (id)
);
